// Кнопка удаления в строке Inventory (поле delete_row в Move Item)
class CRMDeal {
  onLoad() {
    // иконку кнопке задать нельзя (ButtonControl в CRM её не передаёт), поэтому символ корзины в подписи
    this.setFieldProperty('custom_move_items.delete_row', 'label', '\u{1F5D1}')
  }
}

class MoveItem {
  delete_row() {
    const rows = (this.doc.custom_move_items || []).filter((r) => r.idx !== this.currentRowIdx)
    rows.forEach((r, i) => (r.idx = i + 1))
    this.doc.custom_move_items = rows
  }
}
